referenceSolutions.javascript:
export function solve(left, right) {
  const allowed = new Set(right.map((x) => Math.abs(x)));
  const seen = new Set();
  return left.filter((x) => {
    const k = Math.abs(x);
    if (!allowed.has(k) || seen.has(k)) return false;
    seen.add(k);
    return true;
  });
}

